
function [ceq c dceq dc] = cr2(f,t_ult,t_out,df,u,y,stages)

Fout = 0.0   ;
Eenz = 1.937 ;
Csol = 80;   ;
Gsol = 0     ;
k = 0.0257458;
Km = 11.6035;;
Kig = 5.38839;

timeL=0;

%equality
ceq = [];

timeL=0;

%inequality
